ICONS = {
    "map": _MAP_ICON,
    "chat": _CHAT_ICON,
    "camera": _CAMERA_ICON,
    "story": _STORY_ICON,
    "queue": _QUEUE_ICON,
    "profile": _PROFILE_ICON,
    "settings": _SETTINGS_ICON,
    "close": _CLOSE_ICON,
    "check": _CHECK_ICON,
    "send": _SEND_ICON,
    "search": _SEARCH_ICON,
    "filter": _FILTER_ICON,
    "refresh": _REFRESH_ICON,
    "back": _BACK_ICON,
    "upload": _UPLOAD_ICON,
    "warning": _WARNING_ICON,
    "more": _MORE_ICON,
    "question": _QUESTION_ICON,
    "grid": _GRID_ICON,
    "shield": _SHIELD_ICON,
}


def icon(name: str, size: int = 24, cls: str = "") -> str:
    """Return an inline SVG icon."""
    svg = ICONS.get(name, ICONS["question"])
    return f'<span class="pp-icon {cls}" style="width:{size}px;height:{size}px;display:inline-flex;align-items:center;justify-content:center">{svg}</span>'
